def unit_median_correction(unit_ids: Iterable[str], residuals: Iterable[float], shrink: float = 0.25) -> tuple[float, dict[str, float]]:
    ids = [str(value) for value in unit_ids]
    values = np.asarray(list(residuals), dtype=np.float64)
    if len(ids) != values.size or values.size == 0:
        raise ValueError("unit ids and residuals must be non-empty and aligned")
    if not np.isfinite(values).all():
        raise ValueError("residuals must be finite")
    if not np.isfinite(shrink) or shrink < 0:
        raise ValueError("shrink must be finite and non-negative")
    grouped: dict[str, list[float]] = defaultdict(list)
    for unit_id, residual in zip(ids, values):
        grouped[unit_id].append(float(residual))
    medians = {unit_id: float(np.median(unit_values)) for unit_id, unit_values in grouped.items()}
    return -float(shrink) * float(np.mean(list(medians.values()))), medians

def segmented(hgb: np.ndarray, mlp: np.ndarray, rows: list[dict], cfg: dict) -> np.ndarray:
    age = np.asarray([float(r.get("t_end", 0.0)) for r in rows], dtype=np.float32)
    weight = np.where(age <= cfg["threshold"], cfg["low_mlp_weight"], cfg["high_mlp_weight"])
    return (weight * mlp + (1.0 - weight) * hgb).astype(np.float32)

def project(pred: np.ndarray, rows: list[dict], mode: str) -> np.ndarray:
    if mode == "raw":
        return np.asarray(pred, dtype=np.float32)
    out = np.asarray(pred, dtype=np.float32).copy()
    by_unit: dict[str, list[int]] = {}
    for i, row in enumerate(rows):
        by_unit.setdefault(str(row.get("unit_id", "")), []).append(i)
    for idx in by_unit.values():
        order = sorted(idx, key=lambda i: float(rows[i].get("t_end", i)))
        if mode == "isotonic_nonincreasing":
            out[order] = np.clip(pava(out[order]), 0.0, 1.0)
        elif mode == "causal_running_min":
            running = 1.0
            for i in order:
                running = min(running, float(out[i])); out[i] = running
        else:
            raise ValueError(mode)
    return out
